from pathlib import Path

PAGE = Path("pages/1_Professional_Research_Lab.py")
MARKER = "CLEAN SECTOR ROTATION CHART V1"


def replace_once(text, old, new, label):
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{label}: expected 1 match, found {count}")
    return text.replace(old, new, 1)


def main():
    text = PAGE.read_text(encoding="utf-8")
    if MARKER in text:
        print("Clean sector rotation chart already installed")
        return

    old_func = '''def rotation_chart(df):\n    fig = go.Figure()\n    if df is None or df.empty:\n        return fig\n    d = df.dropna(subset=["6M RS vs NIFTY %", "3M Momentum %"]).copy()\n    for q in ["LEADING", "IMPROVING", "WEAKENING", "LAGGING"]:\n        x = d[d["Rotation Quadrant"] == q]\n        if x.empty:\n            continue\n        fig.add_trace(go.Scatter(\n            x=x["6M RS vs NIFTY %"], y=x["3M Momentum %"], mode="markers+text",\n            text=x["Industry"], textposition="top center", name=q,\n            marker={"size": 14 + 4 * x["Sector Score"].clip(0, 10), "opacity": .72},\n            customdata=np.stack([x["Sector Score"], x["Breakout Breadth %"]], axis=-1),\n            hovertemplate="<b>%{text}</b><br>RS6: %{x:.2f}%<br>M3: %{y:.2f}%<br>Score: %{customdata[0]:.1f}/10<br>Breadth: %{customdata[1]:.1f}%<extra></extra>",\n        ))\n    fig.add_vline(x=0, line_dash="dash")\n    fig.add_hline(y=0, line_dash="dash")\n    fig.update_layout(height=560, xaxis_title="6M Relative Strength vs NIFTY (%)", yaxis_title="3M Momentum (%)", margin=dict(l=10, r=10, t=35, b=10))\n    return fig\n'''

    new_func = '''# CLEAN SECTOR ROTATION CHART V1\ndef rotation_chart(df, label_count=10):\n    fig = go.Figure()\n    if df is None or df.empty:\n        return fig\n\n    d = df.dropna(subset=["6M RS vs NIFTY %", "3M Momentum %"]).copy()\n    if d.empty:\n        return fig\n    d = d.sort_values("Sector Score", ascending=False).reset_index(drop=True)\n\n    x_min = min(-5.0, float(d["6M RS vs NIFTY %"].min()) - 4)\n    x_max = max(5.0, float(d["6M RS vs NIFTY %"].max()) + 4)\n    y_min = min(-5.0, float(d["3M Momentum %"].min()) - 4)\n    y_max = max(5.0, float(d["3M Momentum %"].max()) + 4)\n\n    # Soft quadrant backgrounds make the chart readable without adding more text clutter.\n    fig.add_shape(type="rect", x0=0, x1=x_max, y0=0, y1=y_max, fillcolor="rgba(46,160,67,0.055)", line_width=0, layer="below")\n    fig.add_shape(type="rect", x0=x_min, x1=0, y0=0, y1=y_max, fillcolor="rgba(80,160,220,0.055)", line_width=0, layer="below")\n    fig.add_shape(type="rect", x0=0, x1=x_max, y0=y_min, y1=0, fillcolor="rgba(235,87,87,0.055)", line_width=0, layer="below")\n    fig.add_shape(type="rect", x0=x_min, x1=0, y0=y_min, y1=0, fillcolor="rgba(235,87,87,0.035)", line_width=0, layer="below")\n\n    colors = {\n        "LEADING": "#2166ac",\n        "IMPROVING": "#7fc8f8",\n        "WEAKENING": "#ff5b5b",\n        "LAGGING": "#ffb3b3",\n    }\n\n    for q in ["LEADING", "IMPROVING", "WEAKENING", "LAGGING"]:\n        x = d[d["Rotation Quadrant"] == q]\n        if x.empty:\n            continue\n        fig.add_trace(go.Scatter(\n            x=x["6M RS vs NIFTY %"],\n            y=x["3M Momentum %"],\n            mode="markers",\n            name=q,\n            marker={\n                "size": 16 + 2.7 * x["Sector Score"].clip(0, 10),\n                "opacity": 0.88,\n                "color": colors[q],\n                "line": {"width": 1, "color": "rgba(255,255,255,.9)"},\n            },\n            text=x["Industry"],\n            customdata=np.stack([x["Sector Score"], x["Breakout Breadth %"], x["6M Momentum %"], x["12M Momentum %"]], axis=-1),\n            hovertemplate=(\n                "<b>%{text}</b><br>6M RS vs NIFTY: %{x:.2f}%<br>3M Momentum: %{y:.2f}%"\n                "<br>6M Momentum: %{customdata[2]:.2f}%<br>12M Momentum: %{customdata[3]:.2f}%"\n                "<br>Sector Score: %{customdata[0]:.1f}/10<br>Breakout Breadth: %{customdata[1]:.1f}%<extra></extra>"\n            ),\n        ))\n\n    # Only the highest ranked sectors are directly labelled by default.\n    labelled = d.head(max(0, int(label_count))).copy()\n    positions = [(0,18),(16,10),(-16,10),(18,-10),(-18,-10),(0,-18),(24,0),(-24,0)]\n    for i, row in labelled.iterrows():\n        xshift, yshift = positions[i % len(positions)]\n        fig.add_annotation(\n            x=row["6M RS vs NIFTY %"], y=row["3M Momentum %"],\n            text=f"<b>{row['Industry']}</b>", showarrow=False,\n            xshift=xshift, yshift=yshift, font={"size": 11, "color": "#24364b"},\n            bgcolor="rgba(255,255,255,.72)", borderpad=2,\n        )\n\n    fig.add_vline(x=0, line_dash="dash", line_color="rgba(40,50,70,.55)", line_width=1.2)\n    fig.add_hline(y=0, line_dash="dash", line_color="rgba(40,50,70,.55)", line_width=1.2)\n\n    fig.add_annotation(x=x_max, y=y_max, text="<b>LEADING</b><br><span style='font-size:10px'>Strong & sustained</span>", showarrow=False, xanchor="right", yanchor="top", font={"color":"#187a36","size":12})\n    fig.add_annotation(x=x_min, y=y_max, text="<b>IMPROVING</b><br><span style='font-size:10px'>Acceleration building</span>", showarrow=False, xanchor="left", yanchor="top", font={"color":"#2878b8","size":12})\n    fig.add_annotation(x=x_max, y=y_min, text="<b>WEAKENING</b><br><span style='font-size:10px'>Losing strength</span>", showarrow=False, xanchor="right", yanchor="bottom", font={"color":"#cf3232","size":12})\n    fig.add_annotation(x=x_min, y=y_min, text="<b>LAGGING</b><br><span style='font-size:10px'>Weak & deteriorating</span>", showarrow=False, xanchor="left", yanchor="bottom", font={"color":"#cf3232","size":12})\n\n    fig.update_layout(\n        height=650,\n        xaxis={\n            "title": "6M Relative Strength vs NIFTY (%)",\n            "range": [x_min, x_max],\n            "zeroline": False,\n            "showgrid": True,\n            "gridcolor": "rgba(120,130,150,.16)",\n        },\n        yaxis={\n            "title": "3M Momentum (%)",\n            "range": [y_min, y_max],\n            "zeroline": False,\n            "showgrid": True,\n            "gridcolor": "rgba(120,130,150,.16)",\n        },\n        margin=dict(l=25, r=25, t=25, b=25),\n        legend={"orientation":"h", "yanchor":"bottom", "y":1.01, "xanchor":"left", "x":0},\n        hovermode="closest",\n        paper_bgcolor="rgba(0,0,0,0)",\n        plot_bgcolor="rgba(255,255,255,.98)",\n    )\n    return fig\n'''

    text = replace_once(text, old_func, new_func, "rotation_chart")

    old_ui = '''        sectors = sector_table(results, monthlies, bm)\n        st.plotly_chart(rotation_chart(sectors), use_container_width=True)\n        st.dataframe(sectors, use_container_width=True, hide_index=True, column_config={\n            "Sector Score": st.column_config.ProgressColumn(min_value=0, max_value=10, format="%.1f"),\n            "Breakout Breadth %": st.column_config.ProgressColumn(min_value=0, max_value=100, format="%.1f%%"),\n        })\n'''

    new_ui = '''        sectors = sector_table(results, monthlies, bm)\n\n        h1, h2, h3 = st.columns([1.5, 1, 1])\n        with h1:\n            label_mode = st.selectbox("Chart labels", ["Top 8", "Top 12", "All sectors"], index=0, help="Fewer direct labels keep the chart clean; every sector is still available on hover.")\n        with h2:\n            st.metric("Sectors", len(sectors))\n        with h3:\n            st.metric("Current leader", sectors.iloc[0]["Industry"] if not sectors.empty else "N/A")\n        label_count = 8 if label_mode == "Top 8" else 12 if label_mode == "Top 12" else len(sectors)\n\n        st.plotly_chart(rotation_chart(sectors, label_count=label_count), use_container_width=True, config={"displaylogo": False, "responsive": True})\n        st.caption("Tip: direct labels are limited by default to avoid overlap. Hover any bubble to see the sector name, score, relative strength and breakout breadth.")\n\n        if not sectors.empty:\n            summary = sectors[["Industry", "3M Momentum %", "6M Momentum %", "6M RS vs NIFTY %", "Breakout Breadth %", "Sector Score", "Rotation Quadrant"]].copy()\n            summary.insert(0, "Rank", range(1, len(summary) + 1))\n            left, right = st.columns([1.7, 1])\n            with left:\n                st.markdown("#### Sector Momentum Summary")\n                st.dataframe(summary.head(10), use_container_width=True, hide_index=True, column_config={\n                    "Sector Score": st.column_config.ProgressColumn(min_value=0, max_value=10, format="%.1f"),\n                    "Breakout Breadth %": st.column_config.ProgressColumn(min_value=0, max_value=100, format="%.0f%%"),\n                })\n            with right:\n                st.markdown("#### Quick movers")\n                movers = sectors.copy()\n                movers["Acceleration"] = movers["3M Momentum %"] - (movers["6M Momentum %"] / 2)\n                top_up = movers.sort_values("Acceleration", ascending=False).head(5)[["Industry", "Acceleration"]]\n                top_down = movers.sort_values("Acceleration", ascending=True).head(5)[["Industry", "Acceleration"]]\n                st.markdown("**Improving fastest**")\n                st.dataframe(top_up, use_container_width=True, hide_index=True, column_config={"Acceleration": st.column_config.NumberColumn(format="%+.1f")})\n                st.markdown("**Weakening fastest**")\n                st.dataframe(top_down, use_container_width=True, hide_index=True, column_config={"Acceleration": st.column_config.NumberColumn(format="%+.1f")})\n\n        st.dataframe(sectors, use_container_width=True, hide_index=True, column_config={\n            "Sector Score": st.column_config.ProgressColumn(min_value=0, max_value=10, format="%.1f"),\n            "Breakout Breadth %": st.column_config.ProgressColumn(min_value=0, max_value=100, format="%.1f%%"),\n        })\n'''

    text = replace_once(text, old_ui, new_ui, "sector rotation UI")
    PAGE.write_text(text, encoding="utf-8")
    print("Clean sector rotation chart installed")


if __name__ == "__main__":
    main()
